package app.manga.user;import java.security.Principal;import java.util.Map;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/api/v1/users")public class UserController {private final UserRepository users;public UserController(UserRepository u){users=u;}@GetMapping("/me")public Object me(Principal p){AppUser u=users.findByEmail(p.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));return Map.of("data",Map.of("email",u.getEmail(),"displayName",u.getDisplayName()));}}
